import { ListProductStockUseCase } from '../application/ListProductStockUseCase';
import { RegisterProductUseCase } from '../application/RegisterProductUseCase';
import { Persistence } from './Persistence';
import { ProductController } from './ProductController';

/** Wires the catalogue and stock use cases to their adapters. */
export function createProductController(persistence: Persistence): ProductController {
  return new ProductController({
    registerProduct: new RegisterProductUseCase(persistence.products),
    listProductStock: new ListProductStockUseCase(persistence.products),
  });
}

